M2C_UNK workerLockAcquire();                            /* extern */
M2C_UNK workerLockRelease();                            /* extern */
M2C_UNK setVoiceGains(s32, s32, s32, s32, s32);     /* extern */
extern u8 gWorkerThreadActive;

/* If the worker thread is active and voiceIndex is valid (not -1), sets the voice's gains under the worker lock. */ void setVoiceGainsLocked(s32 voiceIndex, u8 gain0, u8 gain1, u8 gain2, u8 gain3) {
    if ((gWorkerThreadActive != 0) & (~voiceIndex != 0)) {
        workerLockAcquire();
        setVoiceGains(voiceIndex, (gain0 & 0xFF) << 0x10, (gain1 & 0xFF) << 0x10, (gain2 & 0xFF) << 0x10, gain3 << 0x10);
        workerLockRelease();
    }
}
